517			Branch:              opts.Branch,
518			CheckpointsCount:    checkpointsCount,
519			FilesTouched:        filesTouched,
520			Sessions:            sessions,
521			TokenUsage:          tokenUsage,
522			CombinedAttribution: combinedAttribution,
523			HasReview:           hasReview,
