543	// UpdateCheckpointSummary updates root-level checkpoint metadata fields that depend
544	// on the full set of sessions already written to the checkpoint.
545	func (s *GitStore) UpdateCheckpointSummary(ctx context.Context, checkpointID id.CheckpointID, combinedAttribution *InitialAttribution) error {
546		if err := ctx.Err(); err != nil {
547			return err //nolint:wrapcheck // Propagating context cancellation
548		}
549	
550		if err := s.ensureSessionsBranch(ctx); err != nil {
551			return fmt.Errorf("failed to ensure sessions branch: %w", err)
552		}
553	
554		parentHash, rootTreeHash, err := s.getSessionsBranchRef()
555		if err != nil {
556			return err
557		}
558	
559		basePath := checkpointID.Path() + "/"
560		checkpointPath := checkpointID.Path()
561		entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
562		if err != nil {
563			return err
564		}
565	
566		rootMetadataPath := basePath + paths.MetadataFileName
567		entry, exists := entries[rootMetadataPath]
568		if !exists {
569			return ErrCheckpointNotFound
570		}
571	
572		summary, err := s.readSummaryFromBlob(entry.Hash)
573		if err != nil {
574			return fmt.Errorf("failed to read checkpoint summary: %w", err)
575		}
576		summary.CombinedAttribution = combinedAttribution
577	
578		metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
579		if err != nil {
580			return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
581		}
582		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
583		if err != nil {
584			return fmt.Errorf("failed to create checkpoint summary blob: %w", err)
585		}
586		entries[rootMetadataPath] = object.TreeEntry{
587			Name: rootMetadataPath,
588			Mode: filemode.Regular,
589			Hash: metadataHash,
590		}
591	
592		newTreeHash, err := s.spliceCheckpointSubtree(ctx, rootTreeHash, checkpointID, basePath, entries)
593		if err != nil {
594			return err
595		}
596	
597		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
598		commitMsg := fmt.Sprintf("Update checkpoint summary for %s", checkpointID)
599		newCommitHash, err := s.createCommit(ctx, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
600		if err != nil {
601			return err
602		}
603	
604		return s.setPrimaryRef(newCommitHash)
605	}

