40	// metadata fields that are identical on every output line.
41	func newTranscriptLine(opts MetadataFields) transcriptLine {
42		return transcriptLine{
43			V:          1,
44			Agent:      opts.Agent,
45			CLIVersion: opts.CLIVersion,
46		}
