71	// Compact converts a full.jsonl transcript into the condensed transcript.jsonl format.
72	// The input must be pre-redacted (via redact.JSONLBytes or
73	// redact.AlreadyRedacted for trusted sources).
74	//
75	// The output format puts version, agent, and cli_version on every line,
76	// merges streaming assistant fragments with the same message ID, and inlines
77	// tool results into the preceding assistant's tool_use blocks:
78	//
79	//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
80	//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"...","name":"...","input":{...},"result":{"output":"...","status":"..."}}]}
81	func Compact(redacted redact.RedactedBytes, opts MetadataFields) ([]byte, error) {
82		content := redacted.Bytes()
83	
84		// Formats that need detection on raw content before line truncation:
85		// - Single-object formats (OpenCode, Gemini): SliceFromLine would cut
86		//   a JSON object mid-value. They handle StartLine as a message-index offset.
87		// - Codex: session_meta header is only on the first line. Codex handles
88		//   StartLine as a response_item index offset.
89		if isOpenCodeFormat(content) {
90			return compactOpenCode(content, opts)
91		}
92	
93		if isGeminiFormat(content) {
94			return compactGemini(content, opts)
95		}
96	
97		// pi: detect on the raw header line. compactPi handles StartLine itself.
98		if isPiFormat(content) {
99			return compactPi(content, opts)
100		}
101	
102		if isCodexFormat(content) {
103			return compactCodex(content, opts)
104		}
105	
106		truncated := transcript.SliceFromLine(content, opts.StartLine)
107		if truncated == nil {
108			truncated = []byte{}
109		}
110	
111		if isCopilotFormat(truncated) {
112			return compactCopilot(truncated, opts)
113		}
114	
115		if isDroidFormat(truncated) {
116			return compactDroid(truncated, opts)
117		}
118	
119		return compactJSONL(truncated, opts)
120	}
