371	// mergeAssistantEntries combines two assistant entries with the same message ID.
372	// Content arrays are concatenated; the later timestamp and token counts win
373	// (streaming fragments report cumulative usage, so the last fragment is final).
374	func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
375		merged := a
376		merged.ts = b.ts
377		if b.inputTokens > 0 {
378			merged.inputTokens = b.inputTokens
379		}
380		if b.outputTokens > 0 {
381			merged.outputTokens = b.outputTokens
382		}
383	
384		var aBlocks, bBlocks []json.RawMessage
385		_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
386		_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
387		all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
388		if data, err := json.Marshal(all); err == nil {
389			merged.content = data
390		}
391	
392		return merged
393	}
394	
395	// inlineToolResults adds "result" fields to matching tool_use blocks in the
396	// assistant entry's content, using outputs from user tool_result entries.
397	func inlineToolResults(assistant, user parsedEntry) parsedEntry {
398		var blocks []map[string]json.RawMessage
399		if json.Unmarshal(assistant.content, &blocks) != nil || len(blocks) == 0 {
400			return assistant
401		}
402	
403		for _, tr := range user.toolResults {
404			// Find the tool_use block matching this tool_use_id.
405			idx := -1
406			for i := len(blocks) - 1; i >= 0; i-- {
407				if unquote(blocks[i]["type"]) == transcript.ContentTypeToolUse {
408					if tr.toolUseID == "" || unquote(blocks[i]["id"]) == tr.toolUseID {
409						idx = i
410						break
411					}
412				}
413			}
414			// No matching tool_use block: do not attach a result to unrelated content.
415			if idx == -1 {
416				continue
417			}
418	
419			blocks[idx]["result"] = buildToolResult(tr)
420		}
421	
422		if data, err := json.Marshal(blocks); err == nil {
423			assistant.content = data
424		}
425	
426		return assistant
427	}
428	
429	// buildToolResult constructs the compact result object for a tool_use block,
430	// including optional rich metadata (file, matchCount) when available.
431	func buildToolResult(tr toolResultEntry) json.RawMessage {
432		r := toolResultJSON{
433			Output:     tr.output,
434			Status:     "success",
435			MatchCount: tr.matchCount,
436		}
437		if tr.isError {
438			r.Status = toolResultStatusError
439		}
440		if tr.file != nil {
441			r.File = &toolResultFileJSON{
442				FilePath: tr.file.filePath,
443				NumLines: tr.file.numLines,
444			}
445		}
446		b, err := json.Marshal(r)
447		if err != nil {
448			return nil
449		}
450		return b
451	}
452	
453	// extractUsageTokens extracts input_tokens and output_tokens from a Claude
454	// message's "usage" object. Returns (0, 0) if usage is absent or malformed.
455	func extractUsageTokens(msg map[string]json.RawMessage) (inputTokens, outputTokens int) {
456		usageRaw, ok := msg["usage"]
457		if !ok {
458			return 0, 0
459		}
460		var usage struct {
461			InputTokens  int `json:"input_tokens"`
462			OutputTokens int `json:"output_tokens"`
463		}
464		if json.Unmarshal(usageRaw, &usage) != nil {
465			return 0, 0
466		}
467		return usage.InputTokens, usage.OutputTokens
468	}
469	
470	// isEmptyContentArray returns true if raw is a JSON empty array (`[]`).
471	func isEmptyContentArray(raw json.RawMessage) bool {
472		var arr []json.RawMessage
473		return json.Unmarshal(raw, &arr) == nil && len(arr) == 0
474	}
475	
476	func hasToolResults(e parsedEntry) bool {
477		return len(e.toolResults) > 0
478	}
479	
480	type toolResultEntry struct {
481		toolUseID string
482		output    string
483		isError   bool
484		// Rich metadata extracted from toolUseResult (optional).
485		file       *toolResultFile // Read/Edit: file path and line count
486		matchCount int             // Grep: number of matching files
487	}
488	
489	// toolResultFile carries structured file metadata from Read/Edit tool results.
490	type toolResultFile struct {
491		filePath string
492		numLines int // 0 if not available (e.g. Edit results)
493	}
494	
495	// enrichToolResults extracts structured metadata from a toolUseResult envelope
496	// and attaches it to the corresponding tool result entries.
497	//
498	// Claude Code's toolUseResult has different shapes per tool:
499	//   - Bash:  {stdout, stderr, interrupted, ...}
500	//   - Read:  {type:"text", file:{filePath, numLines, content, ...}}
501	//   - Grep:  {numFiles, numLines, filenames, content, mode}
502	//   - Edit:  {filePath, oldString, newString, structuredPatch, ...}
503	func enrichToolResults(results []toolResultEntry, tur map[string]json.RawMessage) []toolResultEntry {
504		// Bash-style: stdout provides the output text.
505		if stdout := unquote(tur["stdout"]); stdout != "" {
506			switch len(results) {
507			case 0:
508				// Keep compatibility with transcripts that only include toolUseResult.
509				results = append(results, toolResultEntry{output: stdout})
510			case 1:
511				results[0].output = stdout
512			}
513		}
514	
515		// Read-style: file object with filePath and numLines.
516		if fileRaw, ok := tur["file"]; ok {
517			var file struct {
518				FilePath string `json:"filePath"`
519				NumLines int    `json:"numLines"`
520			}
521			if json.Unmarshal(fileRaw, &file) == nil && file.FilePath != "" {
522				applyToSingleResult(results, func(tr *toolResultEntry) {
523					tr.file = &toolResultFile{filePath: file.FilePath, numLines: file.NumLines}
524				})
525			}
526		}
527	
528		// Edit-style: top-level filePath.
529		if filePath := unquote(tur["filePath"]); filePath != "" {
530			applyToSingleResult(results, func(tr *toolResultEntry) {
531				// Edit results don't have numLines.
532				tr.file = &toolResultFile{filePath: filePath}
533			})
534		}
535	
536		// Grep-style: numFiles as match count.
537		if numFilesRaw, ok := tur["numFiles"]; ok {
538			var n int
539			if json.Unmarshal(numFilesRaw, &n) == nil && n > 0 {
540				applyToSingleResult(results, func(tr *toolResultEntry) {
541					tr.matchCount = n
542				})
543			}
544		}
545	
546		return results
547	}
548	
549	// applyToSingleResult applies fn to the first (and expected only) tool result.
550	// toolUseResult is a single-tool envelope, so this is only meaningful when
551	// there's exactly one result entry.
552	func applyToSingleResult(results []toolResultEntry, fn func(*toolResultEntry)) {
553		if len(results) == 1 {
554			fn(&results[0])
555		}
556	}
557	
558	// parseMessage extracts and parses the "message" field from a JSONL transcript
559	// line. All JSONL agents nest content inside a "message" object.
560	func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
561		msgRaw, ok := raw["message"]
562		if !ok {
563			return nil
564		}
565		var msg map[string]json.RawMessage
566		if json.Unmarshal(msgRaw, &msg) == nil {
567			return msg
568		}
569		return nil
570	}
571	
572	// userContent holds the extracted parts of a user message content array.
573	type userContent struct {
574		text        string
575		images      []json.RawMessage
576		toolResults []toolResultEntry
577	}
578	
579	// extractUserContent separates user message content into text, images, and tool_result entries.
580	// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
581	func extractUserContent(contentRaw json.RawMessage) userContent {
582		var str string
583		if json.Unmarshal(contentRaw, &str) == nil {
584			return userContent{text: textutil.StripIDEContextTags(str)}
585		}
586	
587		var blocks []json.RawMessage
588		if json.Unmarshal(contentRaw, &blocks) != nil {
589			return userContent{}
590		}
591	
592		var uc userContent
593	
594		for _, blockRaw := range blocks {
595			var block map[string]json.RawMessage
596			if json.Unmarshal(blockRaw, &block) != nil {
597				continue
598			}
599			blockType := unquote(block["type"])
600	
601			switch blockType {
602			case "tool_result":
603				var isErr bool
604				if raw, ok := block["is_error"]; ok {
605					_ = json.Unmarshal(raw, &isErr) //nolint:errcheck // best-effort
606				}
607				uc.toolResults = append(uc.toolResults, toolResultEntry{
608					toolUseID: unquote(block["tool_use_id"]),
609					output:    unquote(block["content"]),
610					isError:   isErr,
611				})
612	
613			case "image":
614				uc.images = append(uc.images, blockRaw)
615	
616			case transcript.ContentTypeText:
617				stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
618				if stripped != "" {
619					uc.text += stripped + "\n\n"
620				}
621			}
622		}
623	
624		uc.text = strings.TrimSpace(uc.text)
625		return uc
626	}
627	
628	func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
629		var str string
630		if json.Unmarshal(contentRaw, &str) == nil {
631			return contentRaw
632		}
633	
634		var blocks []map[string]json.RawMessage
635		if json.Unmarshal(contentRaw, &blocks) != nil {
636			return contentRaw
637		}
638	
639		result := make([]map[string]json.RawMessage, 0, len(blocks))
640		for _, block := range blocks {
641			blockType := unquote(block["type"])
642	
643			if blockType == "thinking" || blockType == "redacted_thinking" {
644				continue
645			}
646	
647			if blockType == transcript.ContentTypeToolUse {
648				stripped := make(map[string]json.RawMessage)
649				copyField(stripped, block, "type")
650				copyField(stripped, block, "id")
651				copyField(stripped, block, "name")
652				copyField(stripped, block, "input")
653				result = append(result, stripped)
654				continue
655			}
656	
657			result = append(result, block)
658		}
659	
660		b, err := json.Marshal(result)
661		if err != nil {
662			return contentRaw
663		}
664		return b
665	}
666	
667	// copyField copies a single key from src to dst if it exists.
668	func copyField(dst, src map[string]json.RawMessage, key string) {
669		if v, ok := src[key]; ok {
670			dst[key] = v
671		}
672	}
673	
674	// unquote JSON-decodes a raw message as a string. Returns "" on failure.
675	func unquote(raw json.RawMessage) string {
676		var s string
677		if json.Unmarshal(raw, &s) == nil {
678			return s
679		}
680		return ""
681	}
